const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const core=html.match(/<script id="sim-core">([\s\S]*?)<\/script>/)[1];
const mod=new Function(core+';return {Experiment,DEFAULTS,DT};')();
function run(over, label){
  const s={...mod.DEFAULTS,...over}; const e=new mod.Experiment(s); e.launch();
  const t0=Date.now(); let maxPen=0;
  while(e.running) { e.step(); }
  const st=e.stats(); const cb=e.car.body;
  const sig=e.bricks.reduce((a,b)=>a+b.x*1.3+b.y*7.1,0);
  console.log(label, 'impactV',e.impactSpeed.toFixed(3),'impT',e.impactTime.toFixed(2),'end',e.time.toFixed(2),'crush',e.crush.toFixed(3),'peakG',e.peakDecel.toFixed(1),
   'carX',(cb.x).toFixed(2),'carY',cb.y.toFixed(3),'ang',cb.a.toFixed(3),'displaced',st.displaced,'/',e.bricks.length,'reach',st.reach.toFixed(2),'ms',Date.now()-t0,'sig',sig.toFixed(6));
  return e;
}
run({}, 'default');
run({}, 'default2');
run({carSpeed:5,brickMass:12}, 'slowheavy');
run({carSpeed:10}, 'v10');
run({carSpeed:45}, 'v45');
run({rows:16,columns:4,layers:1}, 'tall');
EOF

