+const DEFAULTS = Object.freeze({
+  carSpeed: 22, columns: 12, rows: 8, layers: 2, brickMass: 2.5,
+  gravity: 9.81, brickFriction: 0.72, brickRestitution: 0.18,
+  carMass: 1250, carWidth: 4.2, carHeight: 1.45, groundFriction: 0.85,
+  scale: 80, brake: true,
