+
+/* ------------------------------------------------------------------ */
+/* Physics engine: sequential impulses, warm starting, speculative     */
+/* contacts, non-linear Gauss-Seidel position correction, islands.     */
+/* ------------------------------------------------------------------ */
+const Physics = (() => {
+  const SLOP = 0.005, BAUMGARTE = 0.2, MAX_CORRECTION = 0.2, SPECULATIVE = 0.02;
+  const RESTITUTION_THRESHOLD = 1.0, MAX_TRANSLATION = 1.0, MAX_ROTATION = 0.5 * Math.PI;
+  const SLEEP_LINEAR = 0.05, SLEEP_ANGULAR = 0.08, SLEEP_TIME = 0.5;
+  const VELOCITY_ITERATIONS = 10, POSITION_ITERATIONS = 4, ANGULAR_DAMPING = 0.05;
+
+  class Shape {
+    constructor(points) {
+      const n = points.length;
+      this.n = n;
+      this.lx = new Float64Array(n); this.ly = new Float64Array(n);
+      this.lnx = new Float64Array(n); this.lny = new Float64Array(n);
+      this.wx = new Float64Array(n); this.wy = new Float64Array(n);
+      this.wnx = new Float64Array(n); this.wny = new Float64Array(n);
+      this.minX = 0; this.minY = 0; this.maxX = 0; this.maxY = 0;
+      this.noGround = false;
+      for (let i = 0; i < n; i++) { this.lx[i] = points[i][0]; this.ly[i] = points[i][1]; }
+      this.computeNormals();
+    }
+    computeNormals() {
+      const n = this.n;
+      for (let i = 0; i < n; i++) {
+        const j = i + 1 < n ? i + 1 : 0;
+        const ex = this.lx[j] - this.lx[i], ey = this.ly[j] - this.ly[i];
+        const len = Math.hypot(ex, ey) || 1;
+        this.lnx[i] = ey / len; this.lny[i] = -ex / len;
+      }
+    }
+    update(b) {
+      const c = b.c, s = b.s;
+      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
+      for (let i = 0; i < this.n; i++) {
+        const lx = this.lx[i], ly = this.ly[i];
+        const x = b.x + c * lx - s * ly, y = b.y + s * lx + c * ly;
+        this.wx[i] = x; this.wy[i] = y;
+        this.wnx[i] = c * this.lnx[i] - s * this.lny[i];
+        this.wny[i] = s * this.lnx[i] + c * this.lny[i];
+        if (x < minX) minX = x; if (x > maxX) maxX = x;
+        if (y < minY) minY = y; if (y > maxY) maxY = y;
+      }
+      this.minX = minX; this.minY = minY; this.maxX = maxX; this.maxY = maxY;
+    }
+  }
+
+  function boxShape(w, h, cx = 0, cy = 0) {
+    const hw = w / 2, hh = h / 2;
+    return new Shape([[cx - hw, cy - hh], [cx + hw, cy - hh], [cx + hw, cy + hh], [cx - hw, cy + hh]]);
+  }
+
+  class Body {
+    constructor(o) {
+      this.id = 0; this.index = -1;
+      this.x = o.x || 0; this.y = o.y || 0; this.a = o.angle || 0;
+      this.vx = 0; this.vy = 0; this.w = 0;
+      this.fx = 0; this.fy = 0; this.torque = 0;
+      this.isStatic = !!o.isStatic;
+      this.mass = this.isStatic ? 0 : o.mass;
+      this.I = this.isStatic ? 0 : o.inertia;
+      this.invMass = this.isStatic ? 0 : 1 / this.mass;
+      this.invI = this.isStatic ? 0 : 1 / this.I;
+      this.shapes = o.shapes || [];
+      this.friction = o.friction ?? 0.5;
+      this.restitution = o.restitution ?? 0;
+      this.layer = o.layer ?? -1;          // -1 collides with every layer
+      this.kind = o.kind || '';
+      this.canSleep = o.canSleep ?? true;
+      this.awake = !this.isStatic;
+      this.sleepTime = 0;
+      this.ext = 0; this.key = 0;
+      this.c = 1; this.s = 0;
+      this.minX = 0; this.minY = 0; this.maxX = 0; this.maxY = 0;
+      this.radius = 0;
+      for (const sh of this.shapes)
+        for (let i = 0; i < sh.n; i++) this.radius = Math.max(this.radius, Math.hypot(sh.lx[i], sh.ly[i]));
+      this.updateTransform();
+    }
+    updateTransform() {
+      this.c = Math.cos(this.a); this.s = Math.sin(this.a);
+      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
+      for (const sh of this.shapes) {
+        sh.update(this);
+        if (sh.minX < minX) minX = sh.minX; if (sh.maxX > maxX) maxX = sh.maxX;
+        if (sh.minY < minY) minY = sh.minY; if (sh.maxY > maxY) maxY = sh.maxY;
+      }
+      this.minX = minX; this.minY = minY; this.maxX = maxX; this.maxY = maxY;
+    }
+    applyForce(fx, fy, px, py) {
+      this.fx += fx; this.fy += fy;
+      this.torque += (px - this.x) * fy - (py - this.y) * fx;
+    }
+    speed() { return Math.hypot(this.vx, this.vy); }
+  }
+
+  /* ---- contact feature ids ---- */
+  const makeId = (iA, iB, tA, tB) => iA | (iB << 8) | (tA << 16) | (tB << 17);
+  const flipId = id => makeId((id >> 8) & 255, id & 255, (id >> 17) & 1, (id >> 16) & 1);
+
+  /* ---- temporary manifold produced by narrow phase ---- */
+  const tm = { type: 0, lnx: 0, lny: 0, lpx: 0, lpy: 0, count: 0,
+    p: [{ lx: 0, ly: 0, id: 0 }, { lx: 0, ly: 0, id: 0 }] };
+  const clipIn = [{ x: 0, y: 0, id: 0 }, { x: 0, y: 0, id: 0 }];
+  const clip1 = [{ x: 0, y: 0, id: 0 }, { x: 0, y: 0, id: 0 }];
+  const clip2 = [{ x: 0, y: 0, id: 0 }, { x: 0, y: 0, id: 0 }];
+  let sepIndex = 0, sepValue = 0;
+
+  function findMaxSeparation(p1, p2, limit) {
+    let best = -Infinity, bi = 0;
+    for (let i = 0; i < p1.n; i++) {
+      const nx = p1.wnx[i], ny = p1.wny[i], vx = p1.wx[i], vy = p1.wy[i];
+      let si = Infinity;
+      for (let j = 0; j < p2.n; j++) {
+        const d = nx * (p2.wx[j] - vx) + ny * (p2.wy[j] - vy);
+        if (d < si) si = d;
+      }
+      if (si > best) { best = si; bi = i; if (best > limit) break; }
+    }
+    sepIndex = bi; sepValue = best;
+  }
+
+  function clipSegment(vin, out, nx, ny, offset, vertexIndexA) {
+    let count = 0;
+    const d0 = nx * vin[0].x + ny * vin[0].y - offset;
+    const d1 = nx * vin[1].x + ny * vin[1].y - offset;
+    if (d0 <= 0) { out[count].x = vin[0].x; out[count].y = vin[0].y; out[count].id = vin[0].id; count++; }
+    if (d1 <= 0) { out[count].x = vin[1].x; out[count].y = vin[1].y; out[count].id = vin[1].id; count++; }
+    if (d0 * d1 < 0 && count < 2) {
+      const t = d0 / (d0 - d1);
+      out[count].x = vin[0].x + t * (vin[1].x - vin[0].x);
+      out[count].y = vin[0].y + t * (vin[1].y - vin[0].y);
+      out[count].id = makeId(vertexIndexA, (vin[0].id >> 8) & 255, 1, 0);
+      count++;
+    }
+    return count;
+  }
+
+  // Convex polygon vs convex polygon (SAT + reference-face clipping).
+  function collidePolygons(sA, A, sB, B, margin) {
+    tm.count = 0;
+    findMaxSeparation(sA, sB, margin);
+    if (sepValue > margin) return 0;
+    const edgeA = sepIndex, sepA = sepValue;
+    findMaxSeparation(sB, sA, margin);
+    if (sepValue > margin) return 0;
+    const edgeB = sepIndex, sepB = sepValue;
+
+    let p1, p2, e1, flip, body2;
+    if (sepB > sepA + 0.1 * SLOP) { p1 = sB; p2 = sA; e1 = edgeB; flip = 1; body2 = A; }
+    else { p1 = sA; p2 = sB; e1 = edgeA; flip = 0; body2 = B; }
+
+    const n1x = p1.wnx[e1], n1y = p1.wny[e1];
+    let inc = 0, minDot = Infinity;
+    for (let j = 0; j < p2.n; j++) {
