+      if (d < minDot) { minDot = d; inc = j; }
+    }
+    const i1 = inc, i2 = inc + 1 < p2.n ? inc + 1 : 0;
+    clipIn[0].x = p2.wx[i1]; clipIn[0].y = p2.wy[i1]; clipIn[0].id = makeId(e1, i1, 0, 1);
+    clipIn[1].x = p2.wx[i2]; clipIn[1].y = p2.wy[i2]; clipIn[1].id = makeId(e1, i2, 0, 1);
