+            inertia: m * (w * w + BRICK_H * BRICK_H) / 12,
+            shapes: [Physics.boxShape(w - BRICK_GAP, BRICK_H)],
+            friction: s.brickFriction, restitution: s.brickRestitution, layer: l, kind: 'brick',
+          });
+          b.x0 = b.x; b.y0 = b.y; b.bucket = brickBucket(l, r, k);
+          this.world.add(b);
+          this.bricks.push(b);
+          buckets[b.bucket].push(b);
+          x += w;
+        }
+      }
+    }
+    this.wallMass = this.bricks.reduce((acc, b) => acc + b.mass, 0);
+  }
+
+  buildCar() {
+    const s = this.s, sx = s.carWidth / 4.2, sy = s.carHeight / 1.45;
+    const comX = COM[0] * sx, comY = COM[1] * sy;
+    const loc = ([x, y]) => [x * sx - comX, y * sy - comY];
+    const lowerBase = CAR_LOWER.map(loc);
+    const lower = new Physics.Shape(lowerBase);
+    const cabin = new Physics.Shape(CAR_CABIN.map(loc));
+    const r = WHEEL_R * sy;
+    const wheelShape = axle => {
+      const pts = [];
+      for (let i = 0; i < 10; i++) {
+        const t = (i / 10) * Math.PI * 2;
+        pts.push([axle * sx - comX + Math.cos(t) * r * 0.97, r - comY + Math.sin(t) * r * 0.97]);
+      }
+      const sh = new Physics.Shape(pts);
+      sh.noGround = true; // tyre/ground interaction is handled by the suspension model
+      return sh;
+    };
+
+    this.aMax = Math.min(8, 0.9 * s.groundFriction * s.gravity);
+    const runup = (s.carSpeed * s.carSpeed) / (2 * this.aMax * 0.97);
+    const gap = 4 + 0.35 * s.carSpeed;
+    const frontLocal = 2.1 * sx - comX;
+    const startFront = this.wallStart - runup - gap;
+
+    const body = new Physics.Body({
+      x: startFront - frontLocal, y: comY, mass: s.carMass,
+      inertia: s.carMass * (s.carWidth * s.carWidth + s.carHeight * s.carHeight) / 14,
+      shapes: [lower, cabin, wheelShape(AXLE_FRONT), wheelShape(AXLE_REAR)],
+      friction: 0.6, restitution: 0.1, layer: -1, kind: 'car', canSleep: false,
+    });
+    this.world.add(body);
+
+    const share = (comX - AXLE_REAR * sx) / ((AXLE_FRONT - AXLE_REAR) * sx);
+    const g = Math.max(s.gravity, 0.5);
+    const wheels = [AXLE_FRONT, AXLE_REAR].map((axle, i) => {
+      const load = s.carMass * g * (i === 0 ? share : 1 - share);
+      const k = load / 0.1;
+      const restLen = (ATTACH_Y - WHEEL_R) * sy + 0.1;
+      return {
+        ax: axle * sx - comX, ay: ATTACH_Y * sy - comY, r, restLen, maxLen: restLen + r,
+        k, c: 2 * 0.35 * Math.sqrt(k * load / g),
+        spin: 0, omega: 0, load: 0, contact: false, skid: false, qx: 0, tVis: ATTACH_Y * sy,
+      };
+    });
+
+    this.car = {
+      body, wheels, sx, sy, comX, comY, lower, lowerBase, frontLocal,
+      maxCrush: 0.7 * sx, startFront,
+    };
+  }
+
+  launch() { if (this.phase === 'idle') this.phase = 'drive'; }
+  get running() { return this.phase !== 'idle' && this.phase !== 'settled'; }
+
+  carPreStep(dt) {
+    const car = this.car, b = car.body, s = this.s, mu = s.groundFriction;
+    if (!b.awake || this.phase === 'idle') return;
+    const Dx = b.s, Dy = -b.c;
+    let totalN = 0;
+    for (const w of car.wheels) {
+      const Px = b.x + b.c * w.ax - b.s * w.ay, Py = b.y + b.s * w.ax + b.c * w.ay;
+      w.load = 0; w.contact = false; w.tVis = w.maxLen;
+      if (Dy < -0.3) {
+        const t = -Py / Dy;
+        if (t < w.maxLen) {
+          const comp = w.maxLen - Math.max(t, 0);
+          const vPx = b.vx - b.w * (Py - b.y), vPy = b.vy + b.w * (Px - b.x);
+          const rate = vPx * Dx + vPy * Dy;
+          let F = w.k * comp + w.c * rate;
+          if (F < 0) F = 0;
+          b.applyForce(-Dx * F, -Dy * F, Px, Py);
+          w.contact = true; w.load = F; w.qx = Px + Dx * t; w.tVis = Math.max(t, w.r * 0.55);
+        }
+      }
+      totalN += w.load;
+    }
+
+    let drive = 0;
+    if (this.phase === 'drive' && totalN > 0) {
+      drive = b.mass * (s.carSpeed - b.vx) * 8;
+      drive = Math.max(-b.mass * this.aMax, Math.min(b.mass * this.aMax, drive));
+      const lim = 0.95 * mu * totalN;
+      drive = Math.max(-lim, Math.min(lim, drive));
+    }
+    for (const w of car.wheels) {
+      w.skid = false;
+      if (!w.contact) { w.spin += w.omega * dt; continue; }
+      const ry = -b.y;
+      const vq = b.vx - b.w * ry;
+      let F = 0;
+      if (this.phase === 'drive') {
+        F = drive * w.load / totalN;
+        w.omega = vq / w.r;
+      } else if (this.phase === 'brake') {
+        const meff = 1 / (b.invMass + b.invI * ry * ry);
+        const lim = mu * w.load;
+        F = Math.max(-lim, Math.min(lim, -vq * meff / dt * 0.5));
+        w.skid = Math.abs(vq) > 0.4;
+        w.omega = w.skid ? 0 : vq / w.r;
+      } else {
+        F = -Math.max(-1, Math.min(1, vq / 0.3)) * 0.015 * w.load;
+        w.omega = vq / w.r;
+      }
+      b.applyForce(F, 0, w.qx, 0);
+      w.spin += w.omega * dt;
+    }
+  }
+
+  step() {
+    if (!this.running) return;
+    const cb = this.car.body;
+    this.prevVx = cb.vx;
+    this.world.step(DT);
+    this.time += DT;
+    this.steps++;
+    this.afterStep();
+  }
+
+  afterStep() {
+    const car = this.car, cb = car.body;
+    let carImpulse = 0, crushImpulse = 0;
+    const frontZone = car.frontLocal - this.crush - 0.9 * car.sx;
+    for (const arb of this.world.active) {
+      const isCar = arb.a === cb || arb.b === cb;
+      if (isCar) {
+        const other = arb.a === cb ? arb.b : arb.a;
+        if (other.kind !== 'brick') continue;
+        for (let i = 0; i < arb.count; i++) {
+          const p = arb.p[i];
+          if (p.nImp <= 0) continue;
+          carImpulse += p.nImp;
+          if (p.vRel < -1.5 && Math.abs(arb.nx) > 0.6) {
+            const lx = cb.c * (p.px - cb.x) + cb.s * (p.py - cb.y);
+            if (lx > frontZone) crushImpulse += p.nImp;
+          }
+        }
+      } else if (this.events.length < 80) {
+        for (let i = 0; i < arb.count; i++) {
+          const p = arb.p[i];
+          if (p.vRel < -2.2 && p.nImp > 0)
+            this.events.push({ x: p.px, y: p.py, v: -p.vRel, ground: arb.a.kind === 'ground' });
+        }
+      }
+    }
+
+    if (carImpulse > 0 && this.impactTime < 0) {
+      this.impactTime = this.time;
+      this.impactSpeed = this.prevVx;
+      this.impactX = cb.x + car.frontLocal;
+      this.impactFlag = true;
+      this.phase = 'impact';
+    }
+    if (crushImpulse > 0 && this.crush < car.maxCrush) {
+      this.crush = Math.min(car.maxCrush, this.crush + crushImpulse / CRUSH_STIFFNESS);
+      for (const i of CAR_FRONT_IDX) car.lower.lx[i] = car.lowerBase[i][0] - this.crush;
+      car.lower.computeNormals();
+      cb.updateTransform();
+    }
+
+    if (this.impactTime >= 0) {
+      const a = (this.prevVx - cb.vx) / DT;
+      this.decelFilt += (a - this.decelFilt) * Math.min(1, DT / 0.012);
+      this.peakDecel = Math.max(this.peakDecel, this.decelFilt / G_STANDARD);
+      if (this.phase === 'impact' && this.s.brake && this.time - this.impactTime > 0.12) this.phase = 'brake';
+    }
+
+    if (this.steps % 12 === 0) {
+      let moving = 0;
+      for (const b of this.bricks) if (b.awake && b.vx * b.vx + b.vy * b.vy > 0.01) moving++;
+      this.movingCount = moving;
+      this.samples.push({ t: this.time, v: Math.abs(cb.vx), m: moving });
+      if (this.impactTime >= 0 && this.time - this.impactTime > 1.5) {
+        if (moving === 0 && cb.speed() < 0.08) this.settleTimer += 12 * DT; else this.settleTimer = 0;
+        if (this.settleTimer >= 0.6 || this.time - this.impactTime > 45) this.phase = 'settled';
+      }
+      if (this.time > 90) this.phase = 'settled';
+    }
+  }
+
+  stats() {
+    let displaced = 0, maxX = -Infinity;
+    for (const b of this.bricks) {
+      const dx = b.x - b.x0, dy = b.y - b.y0;
+      if (dx * dx + dy * dy > 0.0025) displaced++;
+      if (b.maxX > maxX) maxX = b.maxX;
+    }
+    return { displaced, reach: maxX - this.wallEnd };
+  }
+}
+</script>
+
+<!-- ======================================================================
+     RENDERER + UI
+     ====================================================================== -->
+<script>
+'use strict';
+
+function mulberry32(a) {
+  return function () {
+    a |= 0; a = a + 0x6D2B79F5 | 0;
+    let t = Math.imul(a ^ a >>> 15, 1 | a);
+    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
+    return ((t ^ t >>> 14) >>> 0) / 4294967296;
+  };
+}
+
+const BRICK_PALETTE = ['#a8462f', '#b65236', '#9b3f2b', '#bf5e3f', '#8e3826'];
+function shade(hex, f, toward = [34, 22, 20]) {
+  const n = parseInt(hex.slice(1), 16);
+  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
+  const m = (c, t) => Math.round(c + (t - c) * f);
+  return `rgb(${m(r, toward[0])},${m(g, toward[1])},${m(b, toward[2])})`;
+}
+
+class Renderer {
+  constructor(canvas) {
+    this.canvas = canvas;
+    this.ctx = canvas.getContext('2d');
+    this.cam = { x: 0, scale: 40 };
+    this.viewRight = 0;
+    this.xsBuf = new Float64Array(0);
+    const rng = mulberry32(1337);
+    this.buildings = [];
+    for (let x = 0; x < 2400;) {
+      const w = 90 + rng() * 170, h = 40 + rng() * 85;
+      this.buildings.push({ x, w, h, roof: rng() < 0.5, tone: rng() });
+      x += w + 20 + rng() * 90;
+    }
+    this.layerColors = [];
+    for (let l = 0; l < 6; l++) this.layerColors.push(BRICK_PALETTE.map(c => shade(c, l * 0.16)));
+    this.resize();
+  }
+
+  resize() {
+    const dpr = Math.min(window.devicePixelRatio || 1, 2);
+    this.dpr = dpr;
+    this.W = window.innerWidth; this.H = window.innerHeight;
+    this.canvas.width = Math.round(this.W * dpr); this.canvas.height = Math.round(this.H * dpr);
+    this.groundY = Math.round(Math.max(this.H * 0.66, Math.min(this.H - 120, 380)));
+  }
+
+  reset(exp) {
+    this.particles = [];
+    this.skids = [];
+    this.curSkid = [null, null];
+    this.shake = 0; this.shakeX = 0; this.shakeY = 0;
+    this.impactLabel = null;
+    this.rng = mulberry32(20261014);
+    this.updateCamera(exp, 0, true);
+  }
+
+  focus(exp) {
+    const s = exp.s, cb = exp.car.body, half = s.carWidth / 2;
+    let L = Math.min(cb.x - half, exp.wallStart) - 1.2;
+    let R = Math.max(exp.wallEnd, cb.x + half) + 1.8;
+    const top = Math.max(exp.wallHeight, s.carHeight) + 0.9;
+    if (exp.impactTime >= 0) {
+      const n = exp.bricks.length;
+      if (this.xsBuf.length !== n) this.xsBuf = new Float64Array(n);
+      for (let i = 0; i < n; i++) this.xsBuf[i] = exp.bricks[i].x;
+      this.xsBuf.sort();
+      L = Math.min(L, this.xsBuf[Math.floor(n * 0.02)] - 1);
+      R = Math.max(R, this.xsBuf[Math.min(n - 1, Math.floor(n * 0.95))] + 1.5);
+    }
+    return { L, R, top };
+  }
+
+  updateCamera(exp, fdt, snap) {
+    const f = this.focus(exp), cam = this.cam;
+    const availW = Math.max(200, this.viewRight - 60), availH = Math.max(120, this.groundY - 150);
+    let scale = Math.min(exp.s.scale, availW / (f.R - f.L), availH / f.top);
+    scale = Math.max(scale, 4);
+    const cx = (f.L + f.R) / 2;
+    if (snap) { cam.x = cx; cam.scale = scale; }
+    else {
+      const kx = 1 - Math.exp(-fdt * 6), ks = 1 - Math.exp(-fdt * 3);
+      cam.x += (cx - cam.x) * kx;
+      cam.scale *= Math.exp((Math.log(scale) - Math.log(cam.scale)) * ks);
+    }
+    const cb = exp.car.body, half = exp.s.carWidth / 2;
+    const left = this.viewRight / 2 + (cb.x - half - cam.x) * cam.scale;
+    const right = this.viewRight / 2 + (cb.x + half - cam.x) * cam.scale;
+    if (left < 24) cam.x -= (24 - left) / cam.scale;
+    else if (right > this.viewRight - 24) cam.x += (right - (this.viewRight - 24)) / cam.scale;
+  }
+
+  frame(exp, simDt, fdt) {
+    this.consumeEvents(exp);
+    this.updateParticles(simDt);
+    this.updateSkids(exp);
+    this.updateCamera(exp, fdt, false);
+    this.shake *= Math.exp(-fdt * 6);
+    this.shakeX = (this.rng() - 0.5) * 2 * this.shake;
+    this.shakeY = (this.rng() - 0.5) * 2 * this.shake;
+    if (this.impactLabel) this.impactLabel.life -= fdt;
+    this.draw(exp);
+  }
+
+  consumeEvents(exp) {
+    const rng = this.rng;
+    if (exp.impactFlag) {
+      exp.impactFlag = false;
+      this.shake = Math.min(14, 2 + exp.impactSpeed * 0.32);
+      this.impactLabel = { x: exp.impactX, life: 2.6, v: exp.impactSpeed };
+      const n = Math.min(70, 15 + exp.impactSpeed * 2);
+      for (let i = 0; i < n; i++) {
+        this.spawnDust(exp.impactX + (rng() - 0.5) * 0.3, 0.2 + rng() * 1.2,
+          (rng() - 0.2) * 3.5, (rng() - 0.3) * 2.2, 0.15 + rng() * 0.25, 1.4 + rng() * 1.4);
+      }
+      for (let i = 0; i < n * 0.6; i++)
+        this.spawnChip(exp.impactX, 0.2 + rng() * 1.0, exp.impactSpeed * (0.2 + rng() * 0.6), (rng() - 0.2) * 6);
+    }
+    for (const e of exp.events) {
+      if (rng() > 0.4) continue;
+      const k = Math.min(e.v, 14);
+      const dust = 1 + Math.floor(k / 4);
+      for (let i = 0; i < dust; i++)
+        this.spawnDust(e.x + (rng() - 0.5) * 0.2, e.y, (rng() - 0.5) * 1.6, rng() * (e.ground ? 0.9 : 0.4),
+          0.08 + rng() * 0.12 + k * 0.01, 0.9 + rng() * 1.0);
+      if (k > 4 && rng() < 0.6)
+        for (let i = 0; i < 2; i++) this.spawnChip(e.x, e.y, (rng() - 0.5) * k * 0.6, rng() * k * 0.4);
+    }
+    exp.events.length = 0;
+  }
+
+  spawnDust(x, y, vx, vy, r, life) {
+    if (this.particles.length > 700) return;
+    const t = this.rng();
+    this.particles.push({ type: 0, x, y, vx, vy, r, grow: 0.25 + t * 0.35, life, max: life,
+      col: t < 0.5 ? '186,160,134' : '160,140,122' });
+  }
+  spawnChip(x, y, vx, vy) {
+    if (this.particles.length > 700) return;
+    const rng = this.rng;
+    this.particles.push({ type: 1, x, y, vx, vy, a: rng() * 6, w: (rng() - 0.5) * 30,
+      size: 0.025 + rng() * 0.04, life: 1.5 + rng(), max: 2.5, col: BRICK_PALETTE[Math.floor(rng() * 5)] });
+  }
+
+  updateParticles(dt) {
+    if (dt <= 0) return;
+    const ps = this.particles;
+    for (let i = ps.length - 1; i >= 0; i--) {
+      const p = ps[i];
+      p.life -= dt;
+      if (p.life <= 0) { ps[i] = ps[ps.length - 1]; ps.pop(); continue; }
+      if (p.type === 0) {
+        const d = Math.exp(-dt * 1.8);
+        p.vx *= d; p.vy = p.vy * d + 0.12 * dt;
+        p.r += p.grow * dt;
+      } else {
+        p.vy -= 9.81 * dt; p.a += p.w * dt;
+        if (p.y < 0.01 && p.vy < 0) { p.y = 0.01; p.vy *= -0.3; p.vx *= 0.6; p.w *= 0.5; }
+      }
+      p.x += p.vx * dt; p.y += p.vy * dt;
+    }
+  }
+
+  updateSkids(exp) {
+    const car = exp.car, b = car.body;
+    car.wheels.forEach((w, i) => {
+      if (w.skid && w.contact) {
+        const x = b.x + b.c * w.ax - b.s * w.ay;
+        if (!this.curSkid[i]) { this.curSkid[i] = { x0: x, x1: x, depth: i }; this.skids.push(this.curSkid[i]); }
+        this.curSkid[i].x1 = x;
+        if (this.rng() < 0.25) this.spawnDust(x - 0.2, 0.05, -0.6 - this.rng(), 0.3, 0.08, 0.8);
+      } else this.curSkid[i] = null;
+    });
+  }
+
+  /* ------------------------------- drawing ------------------------------- */
+  draw(exp) {
+    const ctx = this.ctx, W = this.W, H = this.H, cam = this.cam, sc = cam.scale;
+    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
+    const gy = this.groundY + this.shakeY;
+    const ox = this.viewRight / 2 + this.shakeX;
+    const view = { ox, gy, sc, x0: cam.x - ox / sc, x1: cam.x + (W - ox) / sc };
+    this.drawBackground(ctx, W, H, gy);
+    this.drawTrack(ctx, W, H, view);
+    this.drawSkidMarks(ctx, view);
+    this.drawShadows(ctx, exp, view);
+    for (let l = exp.s.layers - 1; l >= 0; l--) this.drawLayer(ctx, exp, l, view);
+    this.drawCar(ctx, exp, view);
+    this.drawParticles(ctx, view);
+    this.drawLabels(ctx, exp, view);
+  }
+
+  drawBackground(ctx, W, H, gy) {
+    const horizon = gy - 58, cam = this.cam;
+    const sky = ctx.createLinearGradient(0, 0, 0, horizon);
+    sky.addColorStop(0, '#6f9cc4'); sky.addColorStop(0.6, '#b9d0e2'); sky.addColorStop(1, '#e6ecef');
+    ctx.fillStyle = sky; ctx.fillRect(0, 0, W, horizon + 2);
+    const sun = ctx.createRadialGradient(W * 0.78, horizon * 0.28, 0, W * 0.78, horizon * 0.28, W * 0.35);
+    sun.addColorStop(0, 'rgba(255,248,225,0.55)'); sun.addColorStop(1, 'rgba(255,248,225,0)');
+    ctx.fillStyle = sun; ctx.fillRect(0, 0, W, horizon);
+
+    // distant hills
+    ctx.fillStyle = '#a7b8c6';
+    ctx.beginPath(); ctx.moveTo(0, horizon);
+    for (let x = 0; x <= W + 8; x += 8) {
+      const u = (x + cam.x * 3) / 60;
+      ctx.lineTo(x, horizon - 38 - 16 * Math.sin(u * 0.55) - 9 * Math.sin(u * 1.37 + 1.3) - 5 * Math.sin(u * 3.1));
+    }
+    ctx.lineTo(W, horizon); ctx.closePath(); ctx.fill();
+
+    // test facility buildings
+    const period = 2400, off = -cam.x * 9;
+    for (const b of this.buildings) {
+      let x = ((b.x + off) % period + period) % period - 200;
+      for (; x < W; x += period) {
+        if (x + b.w < 0) continue;
+        const top = horizon - b.h;
+        ctx.fillStyle = b.tone < 0.5 ? '#8797a6' : '#7d8d9c';
+        ctx.fillRect(x, top, b.w, b.h + 2);
+        if (b.roof) {
+          ctx.beginPath(); ctx.moveTo(x - 4, top); ctx.lineTo(x + b.w / 2, top - 16); ctx.lineTo(x + b.w + 4, top); ctx.closePath(); ctx.fill();
+        }
+        ctx.fillStyle = 'rgba(225,236,245,0.35)';
+        for (let wy = top + 12; wy < horizon - 14; wy += 18)
+          for (let wx = x + 10; wx < x + b.w - 16; wx += 22) ctx.fillRect(wx, wy, 11, 7);
+      }
+    }
+    // light poles (closer parallax)
+    const poff = -cam.x * 26, spacing = 300;
+    ctx.strokeStyle = '#5e6b77'; ctx.lineWidth = 3;
+    for (let x = ((poff % spacing) + spacing) % spacing - spacing; x < W + spacing; x += spacing) {
+      ctx.beginPath(); ctx.moveTo(x, horizon + 6); ctx.lineTo(x, horizon - 150); ctx.lineTo(x + 26, horizon - 156); ctx.stroke();
+      ctx.fillStyle = '#e8eef2'; ctx.fillRect(x + 20, horizon - 160, 16, 6);
+    }
+    // infield
+    const inf = ctx.createLinearGradient(0, horizon, 0, gy - 20);
+    inf.addColorStop(0, '#9fae8c'); inf.addColorStop(1, '#8a9b78');
+    ctx.fillStyle = inf; ctx.fillRect(0, horizon, W, gy - 20 - horizon);
+    // barrier fence
+    ctx.fillStyle = 'rgba(70,80,90,0.45)';
