+
+function buildParamUI() {
+  for (const def of PARAMS) {
+    const row = document.createElement('div');
+    row.className = 'param';
+    row.innerHTML = `
+      <div class="param-top">
+        <label for="r-${def.key}">${def.label}</label>
+        <span class="val"><input type="number" id="n-${def.key}" min="${def.min}" max="${def.max}" step="${def.step}"><em>${def.unit}</em></span>
+      </div>
+      <input type="range" id="r-${def.key}" min="${def.min}" max="${def.max}" step="${def.step}">
+      <div class="range-scale"><span>${def.min}</span><span>default ${DEFAULTS[def.key]}</span><span>${def.max}</span></div>`;
+    document.getElementById(def.main ? 'mainParams' : 'advParams').appendChild(row);
+    const range = row.querySelector('input[type=range]'), num = row.querySelector('input[type=number]');
