+function setParam(def, v) {
+  if (!Number.isFinite(v)) { syncUI(); return; }
+  settings[def.key] = quantize(def, v);
+  syncUI();
+  queueRebuild();
+}
+
+function queueRebuild() {
+  if (rebuildQueued) return;
+  rebuildQueued = true;
+  requestAnimationFrame(() => { rebuildQueued = false; resetScene(); });
+}
+
+function resetScene() {
+  exp = new Experiment(settings);
+  acc = 0;
+  renderer.reset(exp);
+  renderActive();
+  updateHud(true);
+}
+
+function runTest() {
+  resetScene();
+  exp.launch();
+}
+
+function renderActive() {
+  const s = exp.s;
+  const halves = exp.bricks.filter(b => b.mass < s.brickMass * 0.99).length;
+  document.getElementById('activeList').innerHTML = `
+    <dt>Car</dt><dd><b>${s.carSpeed.toFixed(1)} m/s</b> (${(s.carSpeed * 3.6).toFixed(0)} km/h) · ${s.carMass.toFixed(0)} kg · ${s.carWidth.toFixed(2)}×${s.carHeight.toFixed(2)} m</dd>
+    <dt>Wall</dt><dd><b>${s.columns}×${s.rows}×${s.layers}</b> · ${exp.bricks.length} pieces (${halves} half) · ${exp.wallMass.toFixed(0)} kg</dd>
+    <dt>Brick</dt><dd><b>${s.brickMass.toFixed(2)} kg</b> · ${BRICK_W.toFixed(2)}×${BRICK_H.toFixed(2)} m · μ ${s.brickFriction.toFixed(2)} · e ${s.brickRestitution.toFixed(2)}</dd>
+    <dt>World</dt><dd>g ${s.gravity.toFixed(2)} m/s² · ground μ ${s.groundFriction.toFixed(2)} · ${s.scale} px/m</dd>
+    <dt>Launch</dt><dd>${(-exp.car.startFront).toFixed(1)} m run-up · ${exp.aMax.toFixed(1)} m/s² · brakes ${s.brake ? 'on' : 'off'}</dd>`;
+}
+
+const PHASE_TEXT = { idle: 'Ready', drive: 'Accelerating', impact: 'Impact', brake: 'Debris in motion', settled: 'Settled' };
+const hud = {
+  status: document.getElementById('status'), speed: document.getElementById('tSpeed'), time: document.getElementById('tTime'),
+  moving: document.getElementById('tMoving'), displaced: document.getElementById('tDisplaced'), impact: document.getElementById('tImpact'),
+  decel: document.getElementById('tDecel'), crush: document.getElementById('tCrush'), reach: document.getElementById('tReach'),
+};
+let hudTimer = 0;
+
+function updateHud(force) {
+  const cb = exp.car.body;
+  let phaseText = PHASE_TEXT[exp.phase];
+  if (exp.phase === 'drive' && Math.abs(exp.s.carSpeed - cb.vx) < 0.15) phaseText = 'Holding speed';
+  if (exp.phase === 'brake' && !exp.s.brake) phaseText = 'Debris in motion';
+  hud.status.textContent = phaseText;
+  hud.status.dataset.phase = exp.phase;
+  const v = Math.abs(cb.vx);
+  hud.speed.innerHTML = `${v.toFixed(1)}<small>m/s · ${(v * 3.6).toFixed(0)} km/h</small>`;
+  hud.time.innerHTML = `${exp.time.toFixed(2)}<small>s${exp.impactTime >= 0 ? ` · +${(exp.time - exp.impactTime).toFixed(2)} post` : ''}</small>`;
+  let moving = 0;
+  for (const b of exp.bricks) if (b.awake && b.vx * b.vx + b.vy * b.vy > 0.01) moving++;
+  if (exp.phase === 'idle') moving = 0;
+  hud.moving.innerHTML = `${moving}<small>/ ${exp.bricks.length}</small>`;
+  const st = exp.stats();
+  hud.displaced.innerHTML = `${st.displaced}<small>${((st.displaced / exp.bricks.length) * 100).toFixed(0)}%</small>`;
+  hud.impact.innerHTML = exp.impactTime >= 0 ? `${exp.impactSpeed.toFixed(2)}<small>m/s</small>` : '—';
+  hud.decel.innerHTML = exp.impactTime >= 0 ? `${exp.peakDecel.toFixed(1)}<small>g</small>` : '—';
+  hud.crush.innerHTML = `${(exp.crush * 100).toFixed(0)}<small>cm</small>`;
+  hud.reach.innerHTML = st.reach > 0.05 ? `+${st.reach.toFixed(1)}<small>m past wall</small>` : '—';
+  drawChart();
+}
+
+const chart = document.getElementById('chart');
+const chartCtx = chart.getContext('2d');
+function drawChart() {
+  const dpr = Math.min(window.devicePixelRatio || 1, 2);
+  const w = chart.clientWidth, h = chart.clientHeight;
+  if (chart.width !== Math.round(w * dpr)) { chart.width = Math.round(w * dpr); chart.height = Math.round(h * dpr); }
+  const c = chartCtx;
+  c.setTransform(dpr, 0, 0, dpr, 0, 0);
+  c.clearRect(0, 0, w, h);
+  const S = exp.samples;
+  const tMax = Math.max(6, exp.time);
+  const vMax = Math.max(exp.s.carSpeed * 1.08, 1);
+  const n = exp.bricks.length;
+  c.strokeStyle = 'rgba(255,255,255,0.06)'; c.lineWidth = 1;
+  for (let i = 1; i < 4; i++) { c.beginPath(); c.moveTo(0, (h * i) / 4); c.lineTo(w, (h * i) / 4); c.stroke(); }
+  if (exp.impactTime >= 0) {
+    const x = (exp.impactTime / tMax) * w;
+    c.strokeStyle = 'rgba(255,90,54,0.5)'; c.setLineDash([3, 3]);
+    c.beginPath(); c.moveTo(x, 0); c.lineTo(x, h); c.stroke(); c.setLineDash([]);
+  }
+  const line = (key, max, color) => {
+    c.strokeStyle = color; c.lineWidth = 1.6; c.beginPath();
+    for (let i = 0; i < S.length; i++) {
+      const x = (S[i].t / tMax) * w, y = h - 3 - (S[i][key] / max) * (h - 8);
+      if (i === 0) c.moveTo(x, y); else c.lineTo(x, y);
+    }
+    c.stroke();
+  };
+  line('m', n, '#ffb547');
+  line('v', vMax, '#ff6b45');
+}
+
+function updateViewport() {
+  renderer.resize();
+  const open = !settingsEl.classList.contains('collapsed') && window.innerWidth > 900;
+  renderer.viewRight = open ? window.innerWidth - settingsEl.offsetWidth - 28 : window.innerWidth;
+}
+
+function frame(now) {
+  const fdt = Math.min(0.1, (now - (frame.last ?? now)) / 1000);
+  frame.last = now;
+  let simDt = 0;
+  if (exp.running) {
+    acc += fdt * timeScale;
+    let n = 0;
+    while (acc >= DT && n < 10 && exp.running) { exp.step(); acc -= DT; n++; }
+    if (n === 10) acc = 0;
+    simDt = n * DT;
+  }
+  renderer.frame(exp, simDt, fdt);
+  hudTimer -= fdt;
+  if (hudTimer <= 0) { updateHud(); hudTimer = 1 / 15; }
+  requestAnimationFrame(frame);
+}
+
+// wiring
+buildParamUI();
+document.getElementById('testBtn').addEventListener('click', runTest);
+document.getElementById('resetBtn').addEventListener('click', resetScene);
+document.getElementById('defaultsBtn').addEventListener('click', () => {
+  Object.assign(settings, DEFAULTS); syncUI(); resetScene();
+});
+document.getElementById('settingsToggle').addEventListener('click', () => {
+  settingsEl.classList.toggle('collapsed');
+  document.getElementById('settingsToggle').textContent = settingsEl.classList.contains('collapsed') ? 'Show' : 'Hide';
+  updateViewport();
+});
+document.querySelectorAll('#timeSeg button').forEach(btn => btn.addEventListener('click', () => {
+  timeScale = parseFloat(btn.dataset.ts);
+  document.querySelectorAll('#timeSeg button').forEach(b => b.classList.toggle('on', b === btn));
+}));
+window.addEventListener('keydown', e => {
+  if (e.target instanceof HTMLInputElement && e.target.type === 'number') return;
+  if (e.code === 'Space' || e.code === 'Enter') { e.preventDefault(); runTest(); }
+  else if (e.key === 'r' || e.key === 'R') resetScene();
+});
+window.addEventListener('resize', () => { updateViewport(); if (exp && !exp.running) renderer.updateCamera(exp, 0, true); });
+
+updateViewport();
+resetScene();
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>

