const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const core0=html.match(/<script id="sim-core">([\s\S]*?)<\/script>/)[1];
const {Physics,DT,Experiment,DEFAULTS}=new Function(core0+';return {Experiment,DEFAULTS,DT,Physics};')();
const box=(w,x,y,bw=0.5,bh=0.24)=>w.add(new Physics.Body({x,y,mass:2.5,inertia:2.5*(bw*bw+bh*bh)/12,shapes:[Physics.boxShape(bw,bh)],friction:0.72,restitution:0.18,layer:0}));
for (const N of [4,10,16,20]){
  const w=new Physics.World(); const a=[];for(let i=0;i<N;i++)a.push(box(w,0,0.12+i*0.24));
  let maxv=0,bad=-1; for(let i=0;i<900;i++){w.step(DT); for(const b of a){const v=Math.hypot(b.vx,b.vy)+Math.abs(b.w); if(v>0.3&&bad<0)bad=i; maxv=Math.max(maxv,v);} }
  console.log('tower',N,maxv.toFixed(3),bad,'awake',a.filter(b=>b.awake).length, 'topY', a[N-1].y.toFixed(4));
}
for (const cfg of [{},{rows:16,columns:24,layers:1}]){
 const e=new Experiment({...DEFAULTS,...cfg}); e.phase='impact';
 let maxv=0; for(let i=0;i<480;i++){ e.world.step(DT); for(const b of e.bricks) maxv=Math.max(maxv,Math.hypot(b.vx,b.vy)); }
 console.log('wall',JSON.stringify(cfg),'maxv',maxv.toFixed(4),'awake',e.bricks.filter(b=>b.awake).length, 'maxdisp', Math.max(...e.bricks.map(b=>Math.hypot(b.x-b.x0,b.y-b.y0))).toFixed(4));
}
EOF

