function warmStart(arb) {
  const a = arb.a, b = arb.b, nx = arb.nx, ny = arb.ny, tx = ny, ty = -nx;
  const mA = a.invMass, mB = b.invMass, iA = a.invI, iB = b.invI;
  for (let i = 0; i < arb.count; i++) {
    const p = arb.p[i];
    const Px = p.nImp * nx + p.tImp * tx, Py = p.nImp * ny + p.tImp * ty;
    a.vx -= mA * Px; a.vy -= mA * Py; a.w -= iA * (p.rAx * Py - p.rAy * Px);
    b.vx += mB * Px; b.vy += mB * Py; b.w += iB * (p.rBx * Py - p.rBy * Px);
  }
}

