const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const core=html.match(/<script id="sim-core">([\s\S]*?)<\/script>/)[1];
const mod=new Function(core+';return {Experiment,DEFAULTS,DT,Physics};')();
const {Physics,DT}=mod;
const box=(w,x,y,bw=0.5,bh=0.24)=>w.add(new Physics.Body({x,y,mass:2.5,inertia:2.5*(bw*bw+bh*bh)/12,shapes:[Physics.boxShape(bw,bh)],friction:0.72,restitution:0.18,layer:0}));
for (const N of [10,16,24]){
  const w=new Physics.World(); const a=[];for(let i=0;i<N;i++)a.push(box(w,0,0.12+i*0.24));
  let maxv=0; for(let i=0;i<900;i++){w.step(DT); for(const b of a){maxv=Math.max(maxv,Math.hypot(b.vx,b.vy)+Math.abs(b.w));} }
  console.log('tower',N,maxv.toFixed(3),'awake',a.filter(b=>b.awake).length,'topErr',(a[N-1].y-(0.12+(N-1)*0.24)).toFixed(4));
}
function run(over, label){
  const s={...mod.DEFAULTS,...over}; const e=new mod.Experiment(s); e.launch();
  const t0=Date.now();
  let preMax=0;
  while(e.running) { e.step(); if(e.impactTime<0) for(const b of e.bricks) preMax=Math.max(preMax, Math.hypot(b.vx,b.vy)); }
  const st=e.stats(); const cb=e.car.body;
  const sig=e.bricks.reduce((a,b)=>a+b.x*1.3+b.y*7.1,0)+cb.x;
  console.log(label.padEnd(10),'preImpMaxV',preMax.toFixed(3),'impV',e.impactSpeed.toFixed(2),'impT',e.impactTime.toFixed(2),'end',e.time.toFixed(1),'crush',e.crush.toFixed(3),'peakG',e.peakDecel.toFixed(1),
   'carDx',(cb.x+e.car.frontLocal).toFixed(2),'carY',cb.y.toFixed(3),'ang',cb.a.toFixed(3),'disp',st.displaced+'/'+e.bricks.length,'reach',st.reach.toFixed(2),'ms',Date.now()-t0,'sig',sig.toFixed(6));
}
run({}, 'default'); run({}, 'default2');
run({carSpeed:5,brickMass:12}, 'slowheavy');
run({carSpeed:5}, 'v5');
run({carSpeed:10}, 'v10');
run({carSpeed:45}, 'v45');
run({brickMass:12}, 'heavy');
run({brickMass:0.5}, 'light');
run({rows:16,columns:4,layers:1}, 'tall');
run({layers:5}, 'L5');
EOF

