const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const core=html.match(/<script id="sim-core">([\s\S]*?)<\/script>/)[1];
const mod=new Function(core+';return {Experiment,DEFAULTS,DT,Physics};')();
function run(over, label){
  const e=new mod.Experiment({...mod.DEFAULTS,...over}); e.launch();
  let maxStep=0, n=0, tot=0, bad=0, maxV=0, impactSteps=[];
  while(e.running){ const t=performance.now(); e.step(); const d=performance.now()-t; tot+=d; n++; if(d>maxStep)maxStep=d;
    if(e.impactTime>=0 && e.time-e.impactTime<1.5) impactSteps.push(d);
    for(const b of e.bricks){ const v=Math.hypot(b.vx,b.vy); if(!Number.isFinite(v)) bad++; if(v>maxV)maxV=v; } }
  impactSteps.sort((a,b)=>a-b);
  const st=e.stats();
  console.log(label.padEnd(10),'bricks',e.bricks.length,'simT',e.time.toFixed(1),'avg ms/step',(tot/n).toFixed(3),'impact p50',(impactSteps[impactSteps.length>>1]||0).toFixed(2),'p95',(impactSteps[Math.floor(impactSteps.length*0.95)]||0).toFixed(2),'max',maxStep.toFixed(1),'maxBrickV',maxV.toFixed(1),'NaN',bad,'crush',e.crush.toFixed(2),'reach',st.reach.toFixed(1),'below', e.bricks.filter(b=>b.minY< -0.05).length);
}
run({columns:24,rows:16,layers:5},'max');
run({columns:24,rows:16,layers:5,carSpeed:45,brickMass:12,carMass:4000},'maxhard');
run({gravity:25,brickRestitution:0.8,brickFriction:0.05},'bouncy');
run({groundFriction:0.1},'icy');
run({carSpeed:45,brickMass:0.5,carMass:400},'light');
run({columns:4,rows:3,layers:1,carSpeed:45},'tiny');
EOF

